import os, sys

def ffloor(v):
    """Rust f64::floor: total, returns a float, inf->inf, nan->nan."""
    if v != v or v == float('inf') or v == float('-inf'): return v
    if v >= 0.0:
        return int(v) if v == int(v) else int(v)
    else:
        iv = int(v)
        return float(iv - 1) if v > iv else float(iv)

def rust_no_guard(x, y):
    # emulate math.fmod for all floats without importing math
    # fmod(x,y) = x - y * trunc(x/y)  (trunc toward zero)
    if y == 0.0:
        mod = float('nan') if x != 0.0 else float('nan')
    else:
        q = x / y
        if q >= 0.0:
            tq = int(q)
        else:
            tq = -int(-q)
        mod = x - y * tq
    if mod != 0.0 and (mod < 0.0) != (y < 0.0):
        div = (x - mod) / y - 1.0
    else:
        div = (x - mod) / y
    if div == 0.0:
        return 0.0 if (x < 0) == (y < 0) else -0.0
    fd = ffloor(div)
    return fd + 1.0 if div - fd > 0.5 else fd

