for cp in range(0xC0, 0x180):
    d = u.decomposition(chr(cp))
    if d and not d.startswith("<"):
        OURS.add(cp)

second = set()
risky = set()
for cp in range(0x110000):
    if 0xD800 <= cp < 0xE000:
        continue
    ch = chr(cp)
    d = u.decomposition(ch)
    if d and not d.startswith("<"):
        risky.add(cp)
        p = d.split()
        if len(p) == 2:
            second.add(int(p[1], 16))
    if u.combining(ch):
        risky.add(cp)

risky.update(range(0xAC00, 0xD7A4))
risky.update(second)
risky -= OURS


def merge(rs, gap):
    out = []
    for cp in sorted(rs):
        if out and cp - out[-1][1] <= gap + 1:
            out[-1][1] = cp
        else:
            out.append([cp, cp])
    return out


A = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz#$"


def enc(n):
    s = ""
    while True:
        d = n & 31
        n >>= 5
        s += A[d + 32] if n else A[d]
        if not n:
            return s


for gap in (0, 1, 2, 4, 8, 16, 32):
    m = merge(risky, gap)
    prev = 0
    out = []
    for s, e in m:
        out.append(enc(s - prev))
        out.append(enc(e - s))
        prev = e + 1
    t = "".join(out)
    print(f"gap={gap} ranges={len(m)} encoded_chars={len(t)}")

